import json
from pathlib import Path
p=Path(__file__).resolve().parent
game=json.loads((p/'game-capture.json').read_text())['gallery'];comparisons=json.loads((p/'comparisons.json').read_text())
items=[{'label':r['name'].split('-',1)[1].replace('-',' ').title(),'path':str(p/r['path']),'group':'Game · 1600 × 1000','caption':'Full game · day / clear · Mini · world detail On'} for r in game]+[{'label':r['id'],'path':str(p/r['path']),'group':'Before / After / Street View','caption':'Before e99e37c1 · final world · Street View © Google · reference only'} for r in comparisons]
html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{font:14px var(--font-sans,system-ui);color:var(--foreground);margin:0}nav{display:flex;gap:8px;align-items:center;margin:0 0 12px}select{flex:1;min-width:0}select,button{font:inherit;color:inherit;background:var(--secondary);border:1px solid var(--border);border-radius:8px;padding:9px}button{cursor:pointer}img{display:block;width:100%;height:auto;border-radius:8px}p{color:var(--muted-foreground);margin:10px 0 0;font-size:12px;line-height:1.5}#caption{min-height:18px}@media(max-width:420px){nav{flex-wrap:wrap}select{flex-basis:100%}}</style></head><body><nav aria-label="Psychiko pictures"><select aria-label="Choose picture" id="pose"></select><button id="prev" aria-label="Previous picture">←</button><button id="next" aria-label="Next picture">→</button></nav><img id="hero" alt=""><p id="caption"></p><p>11 full-game pictures · 39 matched comparisons · photographed kerb occupancy is approximate.</p><script>const items=ITEMS;const select=document.querySelector('#pose'),hero=document.querySelector('#hero'),caption=document.querySelector('#caption'),prev=document.querySelector('#prev'),next=document.querySelector('#next');let group;items.forEach((item,i)=>{if(group?.label!==item.group){group=document.createElement('optgroup');group.label=item.group;select.append(group)}const option=new Option(item.label,i);group.append(option)});let index=1;function show(){const item=items[index];select.value=String(index);hero.src=item.path;hero.alt=item.label;caption.textContent=item.label+' · '+item.caption}select.onchange=()=>{index=Number(select.value);show()};prev.onclick=()=>{index=(index+items.length-1)%items.length;show()};next.onclick=()=>{index=(index+1)%items.length;show()};hero.onload=()=>console.log('Picture ready',index,hero.naturalWidth,hero.naturalHeight);show();console.log('Gallery items',items.length);</script></body></html>'''.replace('ITEMS',json.dumps(items,ensure_ascii=False))
(p/'inline-preview.html').write_text(html)
